// ---------------------------------------------------------------------------
// Cierre determinista post-calculate_estimate.
// Convierte la respuesta del backend en el texto que ve el cliente.
// NINGÚN LLM toca este texto ni la cifra (Adenda 1.1a).
// 21/10 (D39.5): en el caso 4, si el presupuesto es NUEVO (creado === true),
// el texto avisa del email; es justo cuando el flujo lanza WF7 (G2).
// ---------------------------------------------------------------------------

// 1) Extraer la respuesta de calculate_estimate del envoltorio del MCP Client.
//    Forma real verificada: $json.content[0].text. En esta ejecución llegó
//    como OBJETO; en D17.1 (observation) otro dato llegó como STRING JSON.
//    Aceptamos las dos para no depender de cómo lo entregue n8n.
let datos = null;
let incidencia = null;

const bruto = $json.content?.[0]?.text;   // ?. = si algo es undefined, devuelve
                                          // undefined en vez de romper
if (typeof bruto === 'string') {
  try {
    datos = JSON.parse(bruto);            // string JSON -> objeto
  } catch (e) {
    incidencia = 'texto_no_es_json';      // llegó texto, pero no es JSON
  }
} else if (bruto && typeof bruto === 'object') {
  datos = bruto;                          // ya viene como objeto
} else {
  incidencia = 'respuesta_mcp_sin_contenido';
}

// 2) Formato de moneda español. Intl.NumberFormat viene de serie en Node.js.
//    Nota: en es-ES, las cifras de 4 dígitos NO llevan punto de millar
//    ("4840,00 €") porque así lo fija la norma (CLDR/RAE); de 5 en adelante
//    sí ("13.915,00 €"). Es intencionado, no un error.
const eur = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' });

// El backend manda los importes como string decimal ("4840.00") para no
// perder precisión. Aquí solo se muestran, no se calcula nada con ellos,
// así que convertir a Number para formatear es seguro.
function importeValido(valor) {
  const n = Number(valor);
  return (valor !== null && valor !== undefined && valor !== '' && Number.isFinite(n)) ? n : null;
}

// 3) Clasificación. Cada caso exige TODAS sus condiciones; lo que no encaje
//    exactamente cae en el caso 5. Nunca se muestra una cifra "por si acaso".
let caso = 5;
let texto;

if (datos && incidencia === null) {
  const gate   = datos.requiere_aprobacion;
  const motivo = datos.motivo_gate;
  const min    = importeValido(datos.importe_min_con_iva);
  const max    = importeValido(datos.importe_max_con_iva);

  if (datos.status === 'requiere_revision') {
    caso = 1;
  } else if (gate === true && (motivo === 'cambios_estructurales' || motivo === 'ambos')) {
    caso = 2;
  } else if (gate === true && motivo === 'importe_superior_umbral') {
    caso = 3;
  } else if (gate === false && motivo === null && datos.status === 'presupuesto_enviado'
             && min !== null && max !== null && min <= max) {
    caso = 4;
    // D39.5: la frase del email SOLO si este presupuesto se ha creado en esta
    // llamada (creado === true). Es la misma condición con la que el nodo
    // email_presupuesto lanza WF7: en un reintento (creado = false) no sale
    // email, así que tampoco se promete.
    const avisoEmail = datos.creado === true
      ? 'En unos minutos recibirás este resumen en tu email. '   // con espacio final
      : '';                                                       // sin email, sin frase
    texto =
      `Según los datos que nos has facilitado, la estimación orientativa para tu reforma ` +
      `es de entre ${eur.format(min)} y ${eur.format(max)} (IVA incluido).\n\n` +
      `Es una pre-estimación: el presupuesto definitivo se confirma tras una visita ` +
      `técnica, que es gratuita. ` + avisoEmail +                 // la frase va aquí, si toca
      `Si tienes alguna duda o quieres solicitar la visita, dímelo.`;
  } else {
    incidencia = 'combinacion_no_prevista';   // p. ej. un status nuevo del backend
  }
}

// 4) Textos de los casos sin cifra (D18.5: en Gate NUNCA se muestra importe).
//    Casos 2 y 3 (Gate), revisados el 2026-10-04 por D19.3: un cliente con
//    Gate NO pide la visita desde el chat (POST /visits responde 409); es
//    administración quien le llama, avisada al momento por WF2 (email +
//    Telegram). Solo se promete lo que se puede cumplir: "en horario laboral".
if (caso === 1) {
  texto =
    'No hemos podido calcular automáticamente una estimación para tu proyecto. ' +
    'Un técnico lo revisará y se pondrá en contacto contigo.';
} else if (caso === 2) {
  texto =
    'Como tu proyecto incluye cambios estructurales (muros, tabiques o estructura), ' +
    'un técnico tiene que verlo en persona antes de darte una cifra. ' +
    'Nuestro equipo te llamará lo antes posible, en horario laboral, ' +
    'para concertar una visita, que es gratuita.';
} else if (caso === 3) {
  texto =
    'Por las características de tu proyecto, un técnico lo revisará personalmente. ' +
    'Nuestro equipo te llamará lo antes posible, en horario laboral, ' +
    'para darte una información más precisa.';
} else if (caso === 5) {
  texto =
    'Hemos recibido tus datos correctamente. Un técnico revisará tu solicitud ' +
    'y se pondrá en contacto contigo.';
}

// 5) Salida. "output" es el campo que lee el Chat Trigger (VERIFICADO en
//    ejecución real, 2026-09-24). Se devuelven los IDs y el caso para el
//    router, para WF2 y para WF7, pero NUNCA los importes: WF2 y WF7 los leen
//    del backend (aviso del Gate y ficha), con su propia llave.
return {
  json: {
    output: texto,
    caso,                                         // email_presupuesto exige caso 4
    incidencia,                                   // null si todo fue normal
    oportunidad_id: datos?.oportunidad_id ?? null,
    presupuesto_id: datos?.presupuesto_id ?? null,
    requiere_aprobacion: datos?.requiere_aprobacion ?? null,
    motivo_gate: datos?.motivo_gate ?? null,
    // true solo si el presupuesto se creó en ESTA llamada. gate_HITL (WF2) y
    // email_presupuesto (WF7) lo exigen: si n8n reintenta o el cálculo se
    // repite, el backend contesta creado=false y no sale un segundo aviso ni
    // un segundo email (decisión P2 de calculate-estimate; G2 de D39).
    // ?? null: si no se pudo leer la respuesta, "no sabemos" (null) no es lo
    // mismo que "no" (false).
    creado: datos?.creado ?? null,
  },
};

// ---------------------------------------------------------------------------
// chat_tipo_reforma · Aviso técnico si el Agente 2 falla (OpenAI caído, tool rota...). 2026-10-15.
// Entrada: la salida de ERROR de Agente2_asesor. El cliente ya recibe el mensaje de
// error técnico por la otra rama; esto avisa al técnico (WF4). Sin datos del cliente.
// Mode: Run Once for All Items.
// ---------------------------------------------------------------------------
const j = $input.first().json;                                     // { error: ... }
const e = j.error;
const texto = !e ? 'sin detalle' : (typeof e === 'string' ? e
  : [e.code, e.message, e.description].filter((x) => typeof x === 'string' && x.trim() !== '').join(' · ') || 'error sin texto');
let oportunidad_id = null;                                        // del estado de la sesión
try { oportunidad_id = $('Consultar_estado_sesion').first(0).json.oportunidad_id ?? null; } catch (err) { oportunidad_id = null; }
return [{ json: {
  flujo: $workflow.name,                  // este flujo
  nodo: 'Agente2_asesor',                 // el paso que ha fallado
  mensaje_error: `El Agente 2 no pudo responder: ${texto}`,
  oportunidad_id,
  ejecucion_id: String($execution.id),
} }];
